/* Run in Chromium with index.html?test; report results in #test-report. */
(() => {
 const A=window.Hematite,results=[];
 function test(name,fn){try{fn();results.push({name,ok:true});}catch(error){results.push({name,ok:false,error:error.message});}}
 function assert(value,message='assertion failed'){if(!value)throw new Error(message);}
 const click=selector=>{const e=document.querySelector(selector);assert(e,'Missing control: '+selector);e.click();};
 test('Initial map, separate research page, complete tree',()=>{assert(A.state.tiles.length===121);assert(window.MARS_DATA.techs.length===24);assert(A.page==='map');click('#research-tab');assert(A.page==='research');assert(document.querySelectorAll('#tree [data-tech]').length===24);click('#map-tab');assert(A.page==='map');});
 test('Locked research cannot spend points',()=>{A.selectTech('iron');const before=A.state.dp;assert(A.doResearch()===false);assert(A.state.dp===before);});
 test('Survey consumes one point only once',()=>{A.selectTile(2,6);const before=A.state.dp;click('[data-action="survey"]');assert(A.state.dp===before-1);assert(A.state.tiles.find(t=>t.x===2&&t.y===6).surveyed);assert(A.survey()===false);assert(A.state.dp===before-1);});
 test('Research unlocks a usable map action',()=>{A.switchPage('research');A.selectTech('ice');const before=A.state.dp;click('[data-action="research"]');assert(A.state.researched.has('ice'));assert(A.state.dp===before-4);assert(A.doResearch()===false);click('[data-action="back-map"]');assert(A.page==='map');assert(document.querySelector('[data-action="build:iceMine"]'));});
 test('Build, output, upgrade and city growth',()=>{A.selectTile(2,6);click('[data-action="build:iceMine"]');assert(A.state.dp===4);const t=A.state.tiles.find(t=>t.x===2&&t.y===6);assert(t.improvement==='iceMine');assert(A.build('solar')===false);click('#turn-btn');assert(A.state.stock.ice===2);assert(A.state.turn===2);A.selectTech('water');assert(A.doResearch());A.endTurn();A.selectTile(2,6);assert(A.build('waterPlant'));A.selectTile(1,7);A.state.dp+=3;assert(A.build('solar'));assert(A.state.bases[0].level===2);assert(A.income()===4);});
 test('Movement only once per turn; reset restores state',()=>{A.reset();A.selectTile(4,8);assert(A.move());A.selectTile(5,7);assert(A.move()===false);A.endTurn();assert(A.move());const before=A.state.dp;assert(A.claimOutpost());assert(A.state.bases.filter(b=>b.owner===0).length===2);assert(A.state.dp===before-3);assert(A.cost(A.tech('ice'))===5);A.reset();assert(A.state.dp===12&&A.state.turn===1&&A.state.researched.size===2);});
 test('Manufacturing requires inputs and power',()=>{A.reset();A.state.researched.add('electrolysis');A.state.dp=30;A.selectTile(2,8);assert(A.build('oxygenPlant'));A.state.stock.water=0;A.endTurn();const t=A.state.tiles.find(t=>t.x===2&&t.y===8);assert(t.blocked==='材料不足');assert(A.state.stock.hydrogen===0);A.state.stock.water=3;A.endTurn();assert(A.state.stock.hydrogen===1);assert(A.state.stock.water>=0);});
 test('Storm is an event and recoverable, not the game objective',()=>{A.reset();for(let i=0;i<4;i++)A.endTurn();assert(A.state.turn===5&&A.state.storm);assert(A.powerInfo().supply<7);A.endTurn();A.endTurn();assert(!A.state.storm);assert(A.state.logs.some(l=>l.title==='空が晴れた'));});
 test('Lesson controls update selected science explanation',()=>{A.switchPage('research');A.selectTech('electrolysis');assert(document.getElementById('lesson-stage').textContent.includes('水と電力'));click('#next-lesson');assert(document.getElementById('lesson-stage').textContent.includes('水素と酸素'));});
 test('Patrol construction spends points and material, then must wait',()=>{A.reset();A.selectTile(3,7);assert(A.movePatrol(1));A.selectTile(2,7);const before=A.state.dp;assert(A.recruit());assert(A.state.dp===before-4);assert(A.state.stock.resin===1);const fresh=A.state.units.find(u=>u.id===5);assert(fresh&&fresh.moved);A.selectTile(2,6);assert(A.movePatrol(5)===false);});
 test('Patrol combat takes turns and can stop a rival unit',()=>{A.reset();const rival=A.state.units.find(u=>u.id===2);rival.x=3;rival.y=7;A.selectTile(3,7);assert(A.attack());assert(rival.hp===2);assert(A.attack()===false);A.endTurn();assert(A.attack());A.endTurn();assert(A.attack());assert(!A.state.units.includes(rival));});
 test('Rivals wait for the first storm, then advance',()=>{A.reset();const positions=A.state.units.filter(u=>u.owner!==0).map(u=>`${u.x},${u.y}`).join(';');for(let i=0;i<6;i++)A.endTurn();assert(A.state.turn===7);assert(A.state.units.filter(u=>u.owner!==0).map(u=>`${u.x},${u.y}`).join(';')===positions);A.endTurn();assert(A.state.turn===8);assert(A.state.units.filter(u=>u.owner!==0).map(u=>`${u.x},${u.y}`).join(';')!==positions);});
 test('Base capture declares victory, base loss declares defeat',()=>{A.reset();for(const b of A.state.bases.filter(b=>b.owner!==0&&b.x!==8))b.owner=0;A.state.bases.find(b=>b.x===8&&b.y===2).owner=0;const rivalBase=A.state.bases.find(b=>b.x===8&&b.y===8);rivalBase.hp=1;A.state.units=A.state.units.filter(u=>u.owner===0);A.state.units[0].x=7;A.state.units[0].y=8;A.selectTile(8,8);assert(A.attack());assert(A.state.outcome==='victory');assert(document.getElementById('turn-btn').disabled);A.reset();A.state.turn=8;A.state.bases[0].hp=1;A.state.units=A.state.units.filter(u=>u.owner!==0);A.state.units[0].x=2;A.state.units[0].y=6;A.enemyPhase();assert(A.state.outcome==='defeat');});
 A.reset();
 const report=document.createElement('pre');report.id='test-report';report.textContent=JSON.stringify({passed:results.filter(r=>r.ok).length,total:results.length,results},null,2);document.body.appendChild(report);document.title=results.every(r=>r.ok)?'TESTS PASSED':'TESTS FAILED';
})();
